"""Realistic catalogue rows shared by search tests and the benchmark.

The titles exercise every matching path: Russian/English alternative names,
transliteration, genre synonyms, punctuation, and a few unavoidable lookalikes.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from datetime import UTC, datetime

from manga_common.source_models import ChapterSummary, MangaDetail, MangaSummary


@dataclass(frozen=True)
class TitleSpec:
    slug: str
    title: str
    title_en: str | None = None
    title_alt: str | None = None
    genres: tuple[str, ...] = field(default_factory=tuple)
    authors: tuple[str, ...] = field(default_factory=tuple)
    artists: tuple[str, ...] = field(default_factory=tuple)
    content_type: str | None = "манга"
    year: int = 2020
    status: str = "ongoing"
    description: str = ""
    rating: float = 8.0
    rating_count: int = 1_000
    chapters_count: int = 24


