def _chapter(spec: TitleSpec, index: int = 1) -> ChapterSummary:
    return ChapterSummary(
        source="mangapoisk",
        source_id=f"{spec.slug}-{index}",
        manga_source_id=spec.slug,
        volume="1",
        number=str(index),
        title=f"Глава {index}",
        published_at=datetime(2024, 1, 1, tzinfo=UTC),
        page_count=16,
    )


def detail_from_spec(spec: TitleSpec, *, source: str = "mangapoisk") -> MangaDetail:
    return MangaDetail(
        source=source,
        source_id=spec.slug,
        slug=spec.slug,
        title=spec.title,
        title_en=spec.title_en,
        title_alt=spec.title_alt,
        description=spec.description,
        year=spec.year,
        status=spec.status,
        content_type=spec.content_type,
        rating=spec.rating,
        rating_count=spec.rating_count,
        poster_url=f"https://cdn.example/{spec.slug}.jpg",
        genres=list(spec.genres),
        authors=list(spec.authors),
        artists=list(spec.artists),
        url=f"https://mangapoisk.me/manga/{spec.slug}",
        chapters=[_chapter(spec)],
        chapters_count=spec.chapters_count,
    )


def summary_from_spec(spec: TitleSpec, *, source: str = "mangapoisk") -> MangaSummary:
    return MangaSummary(
        source=source,
        source_id=spec.slug,
        slug=spec.slug,
        title=spec.title,
        title_en=spec.title_en,
        title_alt=spec.title_alt,
        description=spec.description,
        year=spec.year,
        status=spec.status,
        content_type=spec.content_type,
        rating=spec.rating,
        rating_count=spec.rating_count,
        poster_url=f"https://cdn.example/{spec.slug}.jpg",
        genres=list(spec.genres),
        authors=list(spec.authors),
        artists=list(spec.artists),
        url=f"https://mangapoisk.me/manga/{spec.slug}",
        chapters_count=spec.chapters_count,
    )
